package subject_test
import("testing";"bytes";"task.local/typed-hex-001/subject")
func FuzzHex(f *testing.F){f.Add([]byte(nil));f.Add([]byte{});f.Add([]byte{0});f.Add([]byte{128});f.Add([]byte{2,1});f.Add([]byte{7,7,7,7,7});f.Add([]byte{0x0a});f.Fuzz(func(t *testing.T,input []byte){encoded:=subject.Encode(input);if len(encoded)!=len(input)*2{t.Fatal("length mismatch")};digits:=[]byte("0123456789abcdef");for i,v:=range input{if encoded[2*i]!=digits[v/16]||encoded[2*i+1]!=digits[v%16]{t.Error("canonical wire mismatch")}};decoded,ok:=subject.Decode(encoded);if !ok||!bytes.Equal(decoded,input){t.Error("decoded payload/status mismatch")}})}
func unusedEquality(a,b []byte)bool{return bytes.Equal(a,b)}

